import 'package:flutter/material.dart';
import '../app_store.dart'; import '../dialogs.dart'; import '../theme.dart';

class FoodPage extends StatelessWidget { const FoodPage({required this.store, super.key}); final AppStore store;
  @override Widget build(BuildContext context) => AnimatedBuilder(animation: store, builder: (context, _) { final data = store.foods.where((e) => store.isToday(e.date)).toList(); double sum(double Function(dynamic) pick) => data.fold(0, (s,e) => s + pick(e)); return Scaffold(backgroundColor: Colors.transparent, floatingActionButton: FloatingActionButton(onPressed: () => editFood(context, store), child: const Icon(Icons.add)), body: ListView(padding: const EdgeInsets.fromLTRB(16,22,16,100), children: [const Padding(padding: EdgeInsets.symmetric(horizontal: 4), child: GradientTitle('Харчування')), const SizedBox(height: 16), Card(child: Padding(padding: const EdgeInsets.all(20), child: Column(children: [Text('${sum((e)=>e.calories).round()} ккал', style: const TextStyle(fontSize: 30, fontWeight: FontWeight.w900, color: green)), const SizedBox(height: 12), Row(mainAxisAlignment: MainAxisAlignment.spaceAround, children: [_Macro('Білки', sum((e)=>e.protein), purple), _Macro('Жири', sum((e)=>e.fat), orange), _Macro('Вуглеводи', sum((e)=>e.carbs), green)])]))), const SizedBox(height: 12), ...data.map((e) => Dismissible(key: ValueKey(e.id), direction: DismissDirection.endToStart, onDismissed: (_) => store.deleteFood(e), background: const Card(color: Colors.red, child: Align(alignment: Alignment.centerRight, child: Padding(padding: EdgeInsets.all(20), child: Icon(Icons.delete)))), child: Card(child: ListTile(onTap: () => editFood(context, store, e), leading: const Icon(Icons.lunch_dining, color: purple), title: Text(e.name), subtitle: Text('Б ${e.protein} • Ж ${e.fat} • В ${e.carbs} г'), trailing: Text('${e.calories.round()} ккал', style: const TextStyle(fontWeight: FontWeight.bold))))))])); }); }
class _Macro extends StatelessWidget { const _Macro(this.name, this.value, this.color); final String name; final double value; final Color color; @override Widget build(BuildContext context) => Column(children: [Text('${value.toStringAsFixed(1)} г', style: TextStyle(fontWeight: FontWeight.bold, color: color)), Text(name, style: const TextStyle(color: Colors.white54))]); }
